<?php require 'config.php';require_login();$u=current_user();$s=db()->prepare('SELECT a.*,d.name doctor_name,d.specialty FROM appointments a JOIN doctors d ON d.id=a.doctor_id WHERE a.user_id=? ORDER BY appointment_date,appointment_time');$s->execute([$u['id']]);$apps=$s->fetchAll(PDO::FETCH_ASSOC);$r=db()->prepare('SELECT * FROM reports WHERE user_id=? ORDER BY report_date DESC');$r->execute([$u['id']]);$reports=$r->fetchAll(PDO::FETCH_ASSOC);$title='Dashboard | MediBook';require 'partials/header.php';?><section class="page-title"><span class="eyebrow">Patient dashboard</span><h1>Hello, <?=e($u['name'])?></h1><p>Manage your demo appointments, consultations and reports.</p></section><section class="stats"><article><b><?=count($apps)?></b><span>Appointments</span></article><article><b><?=count($reports)?></b><span>Reports</span></article><article><b>7/7</b><span>Services tracked</span></article></section><section class="section two"><div><div class="section-head row"><h2>Appointments</h2><a href="doctors.php">Book new</a></div><?php if(!$apps):?><div class="empty">No appointments yet. Choose a doctor to get started.</div><?php endif;foreach($apps as $a):?><article class="item"><div class="datebox"><b><?=e(date('d',strtotime($a['appointment_date'])))?></b><?=e(date('M',strtotime($a['appointment_date'])))?></div><div><h3><?=e($a['doctor_name'])?></h3><p><?=e($a['specialty'])?> • <?=e($a['appointment_time'])?> • <?=e($a['mode'])?></p><span class="badge"><?=e($a['status'])?></span></div></article><?php endforeach;?></div><div><div class="section-head row"><h2>Recent reports</h2><a href="reports.php">View all</a></div><?php foreach(array_slice($reports,0,3) as $x):?><article class="item"><div class="fileicon">PDF</div><div><h3><?=e($x['title'])?></h3><p><?=e($x['doctor_name'])?> • <?=e($x['report_date'])?></p><span class="badge green"><?=e($x['status'])?></span></div></article><?php endforeach;?></div></section><?php require 'partials/footer.php';?>